    <h4 id={"lifecycle-と-object-lock-を組み合わせるときの考え方"} tabIndex={-1}>{"\n                    Lifecycle と Object Lock を組み合わせるときの考え方\n                "}</h4>
    {"\n                "}
    <Diagram id="diag-6" label={"Lifecycle と Object Lock を組み合わせるときの考え方"}/>
    {"\n                "}
    <ul>{"\n                    "}<li>{"\n                        Object Lock で保護されたバージョンは、保持期間中は Lifecycle\n                        の"}<strong>{"期限切れ設定があっても削除されません"}</strong>{"(保持満了後に処理)\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"保持 7 年 → 満了後に自動削除"}</strong>{"」のような要件は\n                        "}<strong>{"Object Lock + Lifecycle"}</strong>{" の組み合わせで実現します\n                    "}</li>{"\n                "}</ul>
    {"\n                "}
    <h4 id={"ベストプラクティス-5"} tabIndex={-1}>{"ベストプラクティス"}</h4>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 33：ベストプラクティス"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"#"}</th><th scope="col">{"ベストプラクティス"}</th></tr></thead><tbody><tr className={"odd"}><td>{"1"}</td><td>{"\n                                    "}<strong>{"データ分類(機密度・保持要件)に基づいて"}</strong>{"ライフサイクルを設計する(技術要件より先に、法規制・社内規程の保持期間を確認)\n                                "}</td></tr><tr className={"even"}><td>{"2"}</td><td>{"\n                                    "}<strong>{"バージョニング有効バケットでは非現行バージョンの期限切れ"}</strong>{"も設定する(放置すると増え続ける)\n                                "}</td></tr><tr className={"odd"}><td>{"3"}</td><td>{"\n                                    "}<strong>{"未完了のマルチパートアップロード"}</strong>{"を自動中止する設定を入れる\n                                "}</td></tr><tr className={"even"}><td>{"4"}</td><td>{"\n                                    保持が必要なデータは\n                                    "}<strong>{"Object Lock と併用"}</strong>{"。削除は保持満了後\n                                "}</td></tr><tr className={"odd"}><td>{"5"}</td><td>{"\n                                    EBS スナップショットは\n                                    "}<strong>{"DLM"}</strong>{"\n                                    で"}<strong>{"作成・保持・削除"}</strong>{"まで自動化(手動運用のスナップショットは「消し忘れ」の温床)\n                                "}</td></tr><tr className={"even"}><td>{"6"}</td><td>{"\n                                    "}<strong>{"ログの保持期間を明示"}</strong>{"(CloudWatch Logs\n                                    は既定で無期限)\n                                "}</td></tr></tbody></table>{"\n                "}</div>
    {"\n                "}
    <h4 id={"試験のポイント-5"} tabIndex={-1}>{"試験のポイント"}</h4>
    {"\n                "}
    <ul>{"\n                    "}<li>{"\n                        「"}<strong>{"一定日数後に低コストストレージへ移行/削除"}</strong>{"」→\n                        "}<strong>{"S3 Lifecycle"}</strong>{"\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"EFS で低頻度アクセスのファイルのコストを下げる"}</strong>{"」→\n                        "}<strong>{"EFS ライフサイクル管理"}</strong>{"\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"保持期間満了までは削除不可、満了後は自動削除"}</strong>{"」→\n                        "}<strong>{"Object Lock + S3 Lifecycle"}</strong>{"\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"EBS スナップショットの自動作成・自動削除"}</strong>{"」→\n                        "}<strong>{"DLM"}</strong>{"(または AWS Backup)\n                    "}</li>{"\n                "}</ul>
