    <h4 id={"vault-lock-と論理的エアギャップボールトの違い"} tabIndex={-1}>{"\n                    Vault Lock と論理的エアギャップボールトの違い\n                "}</h4>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 36：Vault Lock と論理的エアギャップボールトの違い"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"観点"}</th><th scope="col">{"Vault Lock(通常ボールト)"}</th><th scope="col">{"論理的エアギャップボールト"}</th></tr></thead><tbody><tr className={"odd"}><td>{"不変性(WORM)"}</td><td>{"ガバナンス/コンプライアンスを"}<strong>{"選択"}</strong></td><td><strong>{"常にコンプライアンスモード"}</strong></td></tr><tr className={"even"}><td>{"アクセス分離"}</td><td>{"\n                                    "}<strong>{"同じアカウントの管理者権限が及ぶ"}</strong>{"(削除はロックで防ぐが、アクセス自体は分離されない)\n                                "}</td><td><strong>{"本番アカウントの IAM 経路から分離"}</strong>{"(別境界)"}</td></tr><tr className={"odd"}><td>{"暗号化キー"}</td><td>{"お客様の KMS キーを指定"}</td><td>{"AWS 所有キー(既定)または CMK"}</td></tr><tr className={"even"}><td>{"想定脅威"}</td><td>{"誤削除、内部不正、保持期間短縮"}</td><td><strong>{"認証情報を奪った攻撃者"}</strong>{"による破壊・暗号化"}</td></tr></tbody></table>{"\n                "}</div>
