    <h4 id={"s3-レプリケーションの要点"} tabIndex={-1}>{"S3 レプリケーションの要点"}</h4>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 37：S3 レプリケーションの要点"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"項目"}</th><th scope="col">{"内容"}</th></tr></thead><tbody><tr className={"odd"}><td>{"前提"}</td><td>{"\n                                    送信元・送信先"}<strong>{"両方でバージョニング有効"}</strong>{"、レプリケーション用\n                                    "}<strong>{"IAM ロール"}</strong>{"\n                                "}</td></tr><tr className={"even"}><td>{"種類"}</td><td>{"\n                                    "}<strong>{"CRR"}</strong>{"(クロスリージョン:DR・遅延低減・規制対応)/\n                                    "}<strong>{"SRR"}</strong>{"(同一リージョン:ログ集約・アカウント分離)\n                                "}</td></tr><tr className={"odd"}><td>{"暗号化"}</td><td>{"\n                                    "}<strong>{"SSE-KMS\n                                        のオブジェクトをレプリケートするには明示的な設定"}</strong>{"(レプリカ用 KMS キー指定、レプリケーションロールへの\n                                    "}<code>{"kms:Decrypt"}</code>{"/"}<code>{"kms:Encrypt"}</code>{" 権限)が必要\n                                "}</td></tr><tr className={"even"}><td>{"既存オブジェクト"}</td><td>{"\n                                    既定では対象外。"}<strong>{"S3 バッチレプリケーション"}</strong>{"で対応\n                                "}</td></tr><tr className={"odd"}><td>{"削除マーカー"}</td><td>{"\n                                    既定の設定では注意が必要(削除マーカーのレプリケーション設定を確認)\n                                "}</td></tr><tr className={"even"}><td>{"速度保証"}</td><td>{"\n                                    "}<strong>{"S3 Replication Time Control (RTC)"}</strong>{" で 15 分 SLA\n                                    の選択肢\n                                "}</td></tr><tr className={"odd"}><td>{"注意"}</td><td>{"\n                                    レプリケーションは"}<strong>{"バックアップの代替にならない"}</strong>{"(削除や破損も複製される可能性)。"}<strong>{"バージョニング + Object Lock + バックアップ"}</strong>{"と併用\n                                "}</td></tr></tbody></table>{"\n                "}</div>
    {"\n                "}
    <h4 id={"aws-datasync-のセキュリティ"} tabIndex={-1}>{"AWS DataSync のセキュリティ"}</h4>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 38：AWS DataSync のセキュリティ"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"項目"}</th><th scope="col">{"内容"}</th></tr></thead><tbody><tr className={"odd"}><td>{"転送中の暗号化"}</td><td><strong>{"TLS"}</strong>{" による暗号化"}</td></tr><tr className={"even"}><td>{"整合性"}</td><td>{"転送後の"}<strong>{"データ検証(Verify)"}</strong>{"オプション"}</td></tr><tr className={"odd"}><td>{"閉域接続"}</td><td>{"\n                                    "}<strong>{"VPC エンドポイント(PrivateLink)"}</strong>{"経由でサービスと通信可能\n                                "}</td></tr><tr className={"even"}><td>{"アクセス制御"}</td><td>{"\n                                    送信元・送信先ロケーションへの"}<strong>{"最小権限 IAM ロール"}</strong>{"\n                                "}</td></tr><tr className={"odd"}><td>{"保存時"}</td><td>{"送信先(S3・EFS・FSx)の"}<strong>{"暗号化設定が適用"}</strong></td></tr></tbody></table>{"\n                "}</div>
