    <h4 id={"ebs-スナップショットの保護"} tabIndex={-1}>{"EBS スナップショットの保護"}</h4>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 39：EBS スナップショットの保護"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"機能"}</th><th scope="col">{"内容"}</th></tr></thead><tbody><tr className={"odd"}><td><strong>{"DLM"}</strong></td><td>{"\n                                    スナップショットの"}<strong>{"自動作成・保持・削除"}</strong>{"、クロスリージョン/アカウントコピー\n                                "}</td></tr><tr className={"even"}><td><strong>{"EBS スナップショットのロック"}</strong></td><td>{"\n                                    指定期間の"}<strong>{"削除を禁止"}</strong>{"(ガバナンス/コンプライアンス)\n                                "}</td></tr><tr className={"odd"}><td><strong>{"ごみ箱(Recycle Bin)"}</strong></td><td>{"\n                                    誤削除したスナップショット/AMI を"}<strong>{"保持期間内なら復元可能"}</strong>{"\n                                "}</td></tr></tbody></table>{"\n                "}</div>
    {"\n                "}
    <h4 id={"ベストプラクティス-6"} tabIndex={-1}>{"ベストプラクティス"}</h4>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 40：ベストプラクティス"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"#"}</th><th scope="col">{"ベストプラクティス"}</th></tr></thead><tbody><tr className={"odd"}><td>{"1"}</td><td>{"\n                                    "}<strong>{"3-2-1 ルール"}</strong>{"を意識:最低3コピー、2種類の媒体/方式、"}<strong>{"1つは別の場所(別アカウント/別リージョン)"}</strong>{"\n                                "}</td></tr><tr className={"even"}><td>{"2"}</td><td>{"\n                                    バックアップは"}<strong>{"別アカウント"}</strong>{"へコピーし、"}<strong>{"Vault Lock(コンプライアンス)/論理的エアギャップ"}</strong>{"で不変化\n                                "}</td></tr><tr className={"odd"}><td>{"3"}</td><td>{"\n                                    "}<strong>{"AWS Organizations のバックアップポリシー"}</strong>{"で、組織全体に"}<strong>{"一貫したバックアップ"}</strong>{"を強制\n                                "}</td></tr><tr className={"even"}><td>{"4"}</td><td>{"\n                                    "}<strong>{"復元を定期的にテスト"}</strong>{"する(バックアップは「戻せて」初めて価値がある)\n                                "}</td></tr><tr className={"odd"}><td>{"5"}</td><td>{"\n                                    バックアップ用 KMS\n                                    キーの"}<strong>{"キーポリシー"}</strong>{"を、バックアップ関連の主体に"}<strong>{"限定"}</strong>{"\n                                "}</td></tr><tr className={"even"}><td>{"6"}</td><td>{"\n                                    "}<strong>{"S3 レプリケーションだけに頼らない"}</strong>{"(削除・破損の伝播に注意)\n                                "}</td></tr><tr className={"odd"}><td>{"7"}</td><td>{"\n                                    "}<strong>{"RPO/RTO(復旧時点・復旧時間目標)"}</strong>{"から保持期間・頻度・リージョン戦略を決める\n                                "}</td></tr></tbody></table>{"\n                "}</div>
